# Plots of SMD summaries

#' Plots standardised mean difference (SMD) for each covariate and interaction in a [candidates()] data frame. If a threshold value for the SMD is given (via `smd_thresh`) then the output for those seeds with any SMD value exceeding the threshold are greyed, and a message is generated listing the successful seeds.
#' @name plot_smd
#' @param summary_df A data frame generated by [candidates()], containing diagnostic summaries of pss matched samples for a vector of seeds
#' @param smd_thresh Numerical. The threshold above which the SMD is considered 'high'. If `NULL`, no threshold is used and all lines are the same
#' @return A plot with covariates and covariate interactions on the x axis and SMD on the y axis. Lines connect SMD values for the same seed.
#'
#' @export
#' @seealso [candidates()]
#' @examples
#' ## First use `propscores` to create a propensity score data frame
#' ## This example uses the joint approach and specifies p(Z=1) such
#' ## that the expected size of the comparison group is 300
#'
#' eg_j_exp300 <- propscores(
#'   df = eg_data,
#'   cov_cols = c("risk_ass", "category", "sus_age_bin"),
#'   arm_col = "Arm",
#'   intervention_level = "Intervention",
#'   cov_dist = "joint",
#'   pz1_fn = pz1_expectedN(300)
#' )
#'
#' ## Now we can use [candidates()] to tabulate the SMD values for
#' ## four variables and include interactions up to order 3. Because
#' ## `suspect_age` is numeric it will not be included in the interactions.
#'
#' sdf20 = candidates(
#'   df = eg_data,
#'   propscores = eg_j_exp300,
#'   seeds = 1:20,
#'   smd_cols = c("suspect_age", "category", "risk_ass", "sus_age_bin"),
#'   smd_order = 3,
#'   downsample = TRUE,
#'   replace = FALSE
#' )
#'
#' ## Finally we use [plot_smd()] to display the SMD values for each
#' ## covariate and interaction. If a numeric value is given for `smd_thresh`
#' ## then points and lines for seeds for which at lease one SMD values
#' ## is above the threshold are plotted with transparency `alpha = 0.5`.
#'
#' plot_smd(sdf20, smd_thresh = 0.15)
#'
#' @importFrom rlang .data
#'
#'

plot_smd = function(
    summary_df,
    smd_thresh = NULL
    ){
  ## Some checks - think about what could go wrong? Make sure there's a seed column, with unique seeds, and some SMD columns


  ## Start by pivoting longer so there is one SMD column and a 'cov' column

  seed <- covs <- alpha <- SMD <- NULL

  sdf = tidyr::pivot_longer(
    data = summary_df,
    cols = tidyselect::starts_with("SMD"),
    names_to = "covs",
    names_prefix = "SMD_",
    values_to = "SMD"
  )
  sdf$alpha = 1
  if(is.numeric(smd_thresh)){
   sdf_thresh = sdf |>
     dplyr::group_by(seed) |>
     dplyr::mutate(maxSMD = max(SMD))
  sdf = dplyr::left_join(
    sdf,
    sdf_thresh |> dplyr::select(c("seed", "maxSMD")),
    by = "seed")
  sdf$alpha[sdf$maxSMD >= smd_thresh] = 0.5
  }

  plot_out = ggplot2::ggplot(
    data = sdf,
    ggplot2::aes(x=covs, y=SMD, alpha=alpha)
  ) + ggplot2::geom_point() +
    ggplot2::geom_line(ggplot2::aes(group = seed, alpha=alpha)) +
    ggplot2::theme_bw() +
    ggplot2::theme(
      axis.text.x = ggplot2::element_text(angle=90),
      axis.title.x = ggplot2::element_blank(),
      legend.position = "none"
      )
  if(is.numeric(smd_thresh)){
    good_seeds = unique(sdf$seed[sdf$alpha == 1])
    message(
      sprintf(
        "The following seeds generate matched samples for which all SMD values are below the %g threshold: %s",
        smd_thresh,
        paste(good_seeds, collapse = ", "))
    )
  }

  return(plot_out)

}
